# -*- coding: utf-8 -*-
"""Bổ sung Quyển 1 - Chương 2 (Mô hình E-R & chuyển đổi sang quan hệ)."""

MCQ = [
    ("medium", r"Mỗi sinh viên thuộc đúng một lớp, một lớp có nhiều sinh viên. Khi ánh xạ sang mô hình quan hệ, khóa ngoại được đặt ở đâu?",
     [r"Bảng `LOPHOC` chứa `MaSV`", r"Tạo bảng riêng `THUOC(MaSV, MaLop)` bắt buộc", r"Bảng `SINHVIEN` chứa cột `MaLop` tham chiếu `LOPHOC(MaLop)`", r"Cả hai bảng đều chứa khóa ngoại của nhau"],
     "C", r"Quan hệ 1-N: lấy khóa chính của phía 1 (`LOPHOC`) đặt làm khóa ngoại ở phía N (`SINHVIEN`)."),
    ("medium", r"Quan hệ N-N `DANGKY` giữa `SINHVIEN(MaSV)` và `MONHOC(MaMH)` có thuộc tính `Diem`. Lược đồ đúng sau ánh xạ là:",
     [r"`DANGKY(MaSV, MaMH, Diem)` với khóa chính `(MaSV, MaMH)`", r"`DANGKY(MaSV, Diem)` với khóa chính `MaSV`", r"Thêm cột `Diem` vào `SINHVIEN`", r"Thêm cột `Diem` vào `MONHOC`"],
     "A", r"Quan hệ N-N thành một bảng riêng, khóa chính là tổ hợp hai khóa chính; thuộc tính riêng của mối quan hệ đi cùng vào bảng này."),
    ("medium", r"Trong sơ đồ E-R theo Chen, thực thể yếu được biểu diễn bằng:",
     [r"Hình chữ nhật đơn", r"Hình thoi", r"Hình elip nét đứt", r"Hình chữ nhật đường viền đôi"],
     "D", r"Thực thể yếu: hình chữ nhật viền đôi, mối quan hệ định danh: hình thoi viền đôi."),
    ("medium", r"Thuộc tính khóa của một tập thực thể mạnh trong sơ đồ E-R được thể hiện bằng:",
     [r"Gạch chân tên thuộc tính", r"Gạch chân nét đứt", r"In nghiêng", r"Hình elip nét đôi"],
     "A", r"Thuộc tính khóa gạch chân liền; gạch chân nét đứt là khóa bộ phận (discriminator) của thực thể yếu."),
    ("medium", r"Thuộc tính đa trị `Email` của `NHANVIEN(MaNV, HoTen)` khi ánh xạ nên tạo:",
     [r"Thêm cột `Email1, Email2, Email3` vào `NHANVIEN`", r"Bảng `NV_EMAIL(MaNV, Email)` với khóa chính `(MaNV, Email)`", r"Một cột `Email` chứa các địa chỉ cách nhau dấu phẩy", r"Không cần lưu vì là thuộc tính phụ"],
     "B", r"Quy tắc 6: thuộc tính đa trị tạo quan hệ mới gồm khóa chính của thực thể gốc cộng thuộc tính đa trị, bảo đảm tính nguyên tố của giá trị."),
    ("medium", r"Hai thực thể `CONGDAN` và `CCCD` quan hệ 1-1, cả hai phía đều tham gia toàn bộ. Cách ánh xạ nào hợp lý nhất?",
     [r"Luôn luôn bắt buộc tạo bảng thứ ba", r"Thêm khóa ngoại không ràng buộc UNIQUE", r"Có thể gộp thành một bảng duy nhất", r"Không thể ánh xạ"],
     "C", r"Với 1-1 tham gia toàn bộ hai phía, gộp thành một bảng đơn giản và tránh phép nối; hoặc dùng khóa ngoại kèm `UNIQUE`."),
    ("medium", r"Mối quan hệ ba ngôi `CUNGCAP` giữa `NHACUNGCAP`, `VATTU`, `DUAN` (mỗi bộ ba có thể xuất hiện độc lập, quan hệ N-N-N). Khóa chính của bảng `CUNGCAP` là:",
     [r"Chỉ `MaNCC`", r"`(MaNCC, MaVT, MaDA)`", r"`(MaNCC, MaVT)`", r"`(MaVT, MaDA)`"],
     "B", r"Quy tắc 7: quan hệ bậc $\ge 3$ thành bảng riêng có khóa chính gồm khóa của tất cả thực thể tham gia (khi các phía đều là N)."),
    ("medium", r"Thuộc tính kết hợp `DiaChi(SoNha, Duong, Quan, ThanhPho)` thường được ánh xạ thế nào?",
     [r"Bỏ đi các thành phần và chỉ giữ tên `DiaChi`", r"Luôn tạo bảng riêng", r"Tách thành các cột thành phần hoặc gộp thành một cột chuỗi tùy nhu cầu truy vấn", r"Chuyển thành khóa ngoại"],
     "C", r"Thuộc tính kết hợp có thể lưu thành các cột thành phần (dễ truy vấn theo quận) hoặc một cột duy nhất; cả hai đều chỉ chứa giá trị nguyên tố."),
    ("medium", r"Thực thể yếu `THANNHAN(TenTN, QuanHe)` phụ thuộc `NHANVIEN(MaNV)`. Khóa chính của quan hệ `THANNHAN` là:",
     [r"`TenTN`", r"`MaNV`", r"`QuanHe`", r"`(MaNV, TenTN)`"],
     "D", r"Quy tắc 2: khóa chính = khóa thực thể chủ + khóa bộ phận. Cột `MaNV` đồng thời là khóa ngoại tham chiếu `NHANVIEN`."),
    ("medium", r"Trong sơ đồ E-R, đường nối đôi (double line) giữa tập thực thể và mối quan hệ biểu thị:",
     [r"Sự tham gia toàn bộ (total participation)", r"Bản số 1-N", r"Thuộc tính đa trị", r"Thuộc tính suy diễn"],
     "A", r"Đường đôi: mọi thực thể trong tập bắt buộc tham gia ít nhất một lần vào mối quan hệ."),
    ("medium", r"Quan hệ 1-N giữa `PHONG` (1) và `NHANVIEN` (N), mọi nhân viên bắt buộc thuộc một phòng. Cột khóa ngoại `MaPhong` trong `NHANVIEN` nên khai báo:",
     [r"`NULL` tùy ý", r"`UNIQUE`", r"`NOT NULL` kèm khóa ngoại", r"`PRIMARY KEY`"],
     "C", r"Tham gia toàn bộ phía N nghĩa là mỗi nhân viên phải có phòng, nên khóa ngoại phải `NOT NULL`."),
    ("medium", r"Một sơ đồ E-R có 3 thực thể mạnh, 1 mối quan hệ N-N, 1 mối quan hệ 1-N, 1 thuộc tính đa trị (của một thực thể). Số bảng tối thiểu sau ánh xạ là:",
     [r"3", r"5", r"4", r"6"],
     "B", r"3 bảng thực thể + 1 bảng cho N-N + 1 bảng cho thuộc tính đa trị = 5. Quan hệ 1-N chỉ thêm khóa ngoại, không tạo bảng."),
    ("medium", r"Thuộc tính `Tuoi` suy ra từ `NgaySinh` được xếp loại:",
     [r"Thuộc tính đa trị", r"Thuộc tính khóa", r"Thuộc tính kết hợp", r"Thuộc tính suy diễn (derived)"],
     "D", r"Giá trị tính được từ thuộc tính khác; thường không lưu trữ để tránh bất nhất."),

    ("hard", r"Quan hệ tự thân `QUANLY` trên `NHANVIEN`: mỗi nhân viên có tối đa một quản lý trực tiếp, một quản lý quản nhiều nhân viên. Lược đồ đúng là:",
     [r"`NHANVIEN(MaNV, HoTen, MaQL)` với `MaQL` là khóa ngoại tham chiếu `NHANVIEN(MaNV)`, cho phép `NULL`", r"`NHANVIEN(MaNV, HoTen)` và `QUANLY(MaNV)` chỉ chứa một cột",
      r"`NHANVIEN(MaNV, HoTen, MaQL)` với `MaQL NOT NULL`", r"`QUANLY(MaQL, MaNV)` với khóa chính `MaQL`"],
     "A", r"Quan hệ tự thân 1-N thêm khóa ngoại về chính bảng. Phải cho phép `NULL` vì người đứng đầu không có quản lý (nếu `NOT NULL` thì không thể chèn bản ghi gốc)."),
    ("hard", r"Quan hệ tự thân N-N `TIENQUYET` trên `MONHOC` (một môn có nhiều môn tiên quyết và là tiên quyết của nhiều môn). Cách ánh xạ đúng là:",
     [r"Thêm cột `MaMHTQ` vào `MONHOC`", r"Thêm danh sách các môn tiên quyết vào một cột văn bản",
      r"Tạo bảng `TIENQUYET(MaMH, MaMHTQ)` với khóa chính `(MaMH, MaMHTQ)`, cả hai cột là khóa ngoại tham chiếu `MONHOC`", r"Chỉ cần ràng buộc `UNIQUE(MaMH)`"],
     "C", r"N-N tự thân vẫn cần bảng riêng; hai cột cùng tham chiếu `MONHOC` với vai trò khác nhau (môn học và môn tiên quyết)."),
    ("hard", r"Khi xóa một `NHANVIEN`, các `THANNHAN` của nhân viên đó không còn ý nghĩa. Ràng buộc nào phản ánh đúng bản chất thực thể yếu?",
     [r"`ON DELETE SET NULL` trên `MaNV`", r"`ON DELETE NO ACTION` và giữ lại thân nhân",
      r"Bỏ khóa ngoại để dễ xóa", r"`ON DELETE CASCADE` trên khóa ngoại `MaNV` của `THANNHAN`"],
     "D", r"Thực thể yếu phụ thuộc tồn tại vào thực thể chủ nên xóa chủ phải xóa luôn thực thể yếu. Hơn nữa `MaNV` là một phần khóa chính nên không thể là `NULL`."),
    ("hard", r"Nhân viên có thể tham gia cùng một dự án nhiều lần ở các giai đoạn khác nhau (mỗi lần có `NgayBatDau` riêng). Khóa chính phù hợp của `THAMGIA` là:",
     [r"`(MaNV, MaDA)`", r"`(MaNV, MaDA, NgayBatDau)`", r"`(MaNV)`", r"`NgayBatDau`"],
     "B", r"Nếu cặp `(MaNV, MaDA)` lặp lại thì không còn là khóa; phải đưa `NgayBatDau` vào khóa để phân biệt từng lần tham gia."),
    ("hard", r"Sinh viên làm bài sai khi đặt thuộc tính `DiemThi` vào bảng `SINHVIEN` thay vì `KETQUA(MaSV, MaMH, DiemThi)`. Lỗi thiết kế cốt lõi là:",
     [r"`DiemThi` phụ thuộc vào cả sinh viên lẫn môn học; đặt ở `SINHVIEN` sẽ không biểu diễn được điểm của nhiều môn mà không lặp bản ghi",
      r"`DiemThi` quá lớn để lưu",
      r"`DiemThi` là thuộc tính suy diễn",
      r"Không có lỗi gì"],
     "A", r"Thuộc tính của quan hệ N-N thuộc về cặp thực thể, không thuộc riêng thực thể nào."),
    ("hard", r"`PHONG(MaPhong)` 1-N `NHANVIEN(MaNV)`, quan hệ `CONGTAC` có thuộc tính `NgayBatDau`. Thuộc tính này sau ánh xạ nằm ở đâu?",
     [r"Bảng `PHONG`", r"Tạo bảng `CONGTAC` bắt buộc", r"Bảng `NHANVIEN` (phía N)", r"Cả hai bảng"],
     "C", r"Với quan hệ 1-N, các thuộc tính riêng của mối quan hệ chuyển sang bảng phía N cùng khóa ngoại, vì mỗi nhân viên chỉ có một phòng."),
    ("hard", r"Thực thể `SINHVIEN` có hai khóa ứng viên là `MaSV` và `CCCD`. Cách xử lý đúng khi ánh xạ là:",
     [r"Bắt buộc dùng cả hai làm khóa chính", r"Chọn một khóa làm khóa chính, khóa còn lại khai báo `UNIQUE NOT NULL`",
      r"Bỏ đi `CCCD`", r"Dùng cả hai làm khóa ngoại"],
     "B", r"Một quan hệ chỉ có một khóa chính; các khóa ứng viên còn lại vẫn phải đảm bảo duy nhất và không rỗng bằng `UNIQUE` và `NOT NULL`."),
    ("hard", r"Cho quan hệ 1-1 `QUANLY` giữa `NHANVIEN` (tham gia không toàn bộ) và `PHONG` (tham gia toàn bộ: mỗi phòng có đúng một trưởng phòng). Phương án ánh xạ tối ưu là:",
     [r"Thêm `MaNV` vào `PHONG` làm khóa ngoại `UNIQUE NOT NULL` tham chiếu `NHANVIEN`", r"Thêm `MaPhong` vào `NHANVIEN` làm khóa ngoại `NOT NULL`",
      r"Gộp hai bảng thành một", r"Tạo ba bảng gồm `NHANVIEN`, `PHONG`, `QUANLY` mà không có ràng buộc UNIQUE"],
     "A", r"Đặt khóa ngoại về phía tham gia toàn bộ (`PHONG`) để tránh `NULL`: mỗi phòng bắt buộc có `MaNV` duy nhất. Đặt ở `NHANVIEN` sẽ sinh nhiều giá trị `NULL` vì đa số nhân viên không làm trưởng phòng."),
]

SHORT = [
    (r"Viết lệnh `CREATE TABLE` cho quan hệ N-N `DANGKY(MaSV, MaMH, HocKy, Diem)` với khóa chính và khóa ngoại phù hợp. Lưu ý một sinh viên có thể học lại môn ở học kỳ khác.",
     """```sql
CREATE TABLE DANGKY (
  MaSV   VARCHAR(10) NOT NULL REFERENCES SINHVIEN(MaSV),
  MaMH   VARCHAR(10) NOT NULL REFERENCES MONHOC(MaMH),
  HocKy  VARCHAR(10) NOT NULL,
  Diem   DECIMAL(4,2) CHECK (Diem BETWEEN 0 AND 10),
  PRIMARY KEY (MaSV, MaMH, HocKy)
);
```""",
     r"Do cho phép học lại, `HocKy` phải thuộc khóa chính để phân biệt các lần đăng ký."),
    (r"Phân biệt thuộc tính suy diễn và thuộc tính lưu trữ; nêu một lợi ích và một rủi ro của việc lưu thuộc tính suy diễn.",
     r"Thuộc tính lưu trữ có giá trị ghi trực tiếp (vd `NgaySinh`); thuộc tính suy diễn tính được từ thuộc tính khác (vd `Tuoi`). Lợi ích khi lưu: truy vấn nhanh, không phải tính lại. Rủi ro: dễ bất nhất khi dữ liệu nguồn đổi (vd `Tuoi` lỗi thời).",
     r"Giải pháp: dùng cột tính toán (computed column) hoặc view."),
    (r"Một bác sĩ khám nhiều bệnh nhân, một bệnh nhân khám nhiều bác sĩ, mỗi lần khám có ngày giờ và kết luận. Xác định bản số và lược đồ quan hệ.",
     r"Bản số N-N. Lược đồ: `BACSI(MaBS,...)`, `BENHNHAN(MaBN,...)`, `KHAM(MaBS, MaBN, NgayGio, KetLuan)` với khóa chính `(MaBS, MaBN, NgayGio)`.",
     r"Cần `NgayGio` trong khóa vì cùng một cặp bác sĩ - bệnh nhân có thể khám nhiều lần."),
]

ESSAY = [
    (r"Thiết kế E-R và ánh xạ cho hệ thống quản lý thư viện",
     r"Thư viện quản lý SÁCH (mã sách, tên, nhà xuất bản, nhiều tác giả), ĐỘC GIẢ (mã, họ tên, nhiều số điện thoại, địa chỉ gồm số nhà - đường - quận), PHIẾU MƯỢN (mã phiếu, ngày mượn). Một phiếu mượn do một độc giả lập và gồm nhiều cuốn sách (kèm hạn trả và ngày trả thực tế). Một cuốn có nhiều bản sao vật lý (BANSAO) chỉ định danh bằng số thứ tự trong sách. Yêu cầu: a) vẽ/mô tả các thực thể, thuộc tính, bản số; b) xác định thực thể yếu; c) ánh xạ sang lược đồ quan hệ và viết khóa chính, khóa ngoại.",
     [r"Bước 1 - Thực thể và bản số: `SACH`, `DOCGIA`, `PHIEUMUON`, `BANSAO` (yếu, phụ thuộc `SACH`, khóa bộ phận `SoThuTu`). `DOCGIA` 1-N `PHIEUMUON`. `PHIEUMUON` N-N `BANSAO` qua mối quan hệ `CHITIETMUON(HanTra, NgayTraTT)`. `SACH` 1-N `BANSAO` (định danh). `SACH` có thuộc tính đa trị `TacGia`; `DOCGIA` có thuộc tính đa trị `SDT` và thuộc tính kết hợp `DiaChi`.",
      r"Bước 2 - Thực thể mạnh: `SACH(MaSach, TenSach, NXB)`, `DOCGIA(MaDG, HoTen, SoNha, Duong, Quan)`, `PHIEUMUON(MaPhieu, NgayMuon, MaDG)` với `MaDG` là khóa ngoại `NOT NULL`.",
      r"Bước 3 - Thực thể yếu: `BANSAO(MaSach, SoThuTu)` khóa chính `(MaSach, SoThuTu)`, `MaSach` là khóa ngoại `ON DELETE CASCADE`.",
      r"Bước 4 - Thuộc tính đa trị: `SACH_TACGIA(MaSach, TacGia)` khóa chính `(MaSach, TacGia)`; `DOCGIA_SDT(MaDG, SDT)` khóa chính `(MaDG, SDT)`.",
      r"Bước 5 - Quan hệ N-N: `CHITIETMUON(MaPhieu, MaSach, SoThuTu, HanTra, NgayTraTT)` khóa chính `(MaPhieu, MaSach, SoThuTu)`; khóa ngoại `(MaPhieu)` tham chiếu `PHIEUMUON`, `(MaSach, SoThuTu)` tham chiếu `BANSAO`.",
      r"Kết luận: lược đồ gồm 7 bảng, không có thuộc tính đa trị hay kết hợp chưa nguyên tố, mọi bản số đã được thể hiện bằng khóa ngoại hoặc bảng trung gian."]),
]
